/* MOBIMORY / Fahrzeugplattform 1.0.5.2-dev
   Phase-1-Korrekturlauf auf Basis 1.0.5.1-dev:
   - zentrale Fahrzeug-Verfügbarkeit für Nutzung und Verleih
   - Verleih: Leiher/Gast getrennt von Fahrer/Skipper, echte Fahrerlaubnisprüfung
   - Wohnmobil: B wird auch durch passende höhere Klassen erfüllt; Anhängerregeln nur bei Anhängerbetrieb
   - Ereignisarten: Bearbeiten direkt an der gewählten Zeile
   - Tiere: dynamische Nachweise / Impfungen / Titer / Reiseunterlagen
   - Fahrzeug: dynamische Fahrzeugprüfungen
   - Komponenten: Wartungen und Prüfungen direkt am Bauteil
   - Werkstatt: keine Wartungs-/Prüfregeln mehr direkt anlegen
   - Wasserski-Runs direkt im Cockpit und in der Nutzungsansicht
   Reisecheck 1.0.6 bleibt bewusst außerhalb dieses Patches. */

const FP1052_VERSION='1.0.5.2-dev';
const FP1052={lendingDraft:null,maintenanceData:null};

function fp1052DateInput(v){return v?String(v).slice(0,10):''}
function fp1052DateTimeInput(v){return typeof fp104LocalInput==='function'?fp104LocalInput(v):fp105IsoLocalValue(v)}
function fp1052Fmt(v){return typeof fp104Date==='function'?fp104Date(v):fmtDate(v)}
function fp1052Norm(v){return typeof fp105NormText==='function'?fp105NormText(v):String(v||'').toLowerCase()}
function fp1052DateLabel(v){return v?fp1052Fmt(v):'–'}
function fp1052LocalDayStart(v){if(!v)return null;const d=new Date(v+'T00:00:00');return Number.isNaN(d.getTime())?null:d}
function fp1052LocalDayEnd(v){if(!v)return null;const d=new Date(v+'T23:59:59');return Number.isNaN(d.getTime())?null:d}
function fp1052AsDate(v){if(!v)return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d}
function fp1052Overlap(a1,a2,b1,b2){return a1<=b2&&b1<=a2}
function fp1052RangeText(start,end){const a=fp1052DateLabel(start),b=end&&Number.isFinite(new Date(end).getTime())?fp1052DateLabel(end):'offen';return `${a} bis ${b}`}

/* ========================================================================== */
/*  Zentrale Fahrzeug-Verfügbarkeit                                          */
/* ========================================================================== */

function fp1052UsageRange(row){
  const f=row?.fields||{},status=String(f.Status||'');
  if(!['Aktiv','Geplant','Vorbereitet'].includes(status))return null;
  const start=fp1052AsDate(f.GeplanterBeginn||f.Beginn);
  if(!start)return null;
  let end=fp1052AsDate(f.GeplantesEndeDatum||f.Ende);
  if(!end){end=status==='Aktiv'?new Date(8640000000000000):new Date(start.getTime()+24*3600*1000-1)}
  return {start,end};
}
function fp1052LendingRange(row){
  const f=row?.fields||{},status=String(f.Status||'');
  if(f.Aktiv===false||f.Archiviert===true||['Beendet','Archiviert','Storniert'].includes(status))return null;
  if(!['Aktiv','Vorbereitet','Geplant',''].includes(status))return null;
  const start=fp1052AsDate(f.Beginn),end=fp1052AsDate(f.Ende)||new Date(8640000000000000);
  if(!start)return null;return {start,end};
}
async function fp1052VehicleConflicts(api,vehicleId,start,end,{excludeUsageId='',excludeLendingId=''}={}){
  const a=fp1052AsDate(start),b=fp1052AsDate(end)||a;if(!a||!b)return [];
  const [us,ls]=await Promise.all([fp105SafeList(api,'Nutzungen'),fp105SafeList(api,'Fahrzeugueberlassungen')]),out=[];
  for(const u of us){
    if(String(u.fields.FahrzeugId)!==String(vehicleId)||String(u.id)===String(excludeUsageId||''))continue;
    const r=fp1052UsageRange(u);if(!r||!fp1052Overlap(a,b,r.start,r.end))continue;
    out.push({type:'Nutzung',id:String(u.id),title:u.fields.Title||'Nutzung',status:u.fields.Status||'',start:r.start,end:r.end});
  }
  for(const l of ls){
    if(String(l.fields.FahrzeugId)!==String(vehicleId)||String(l.id)===String(excludeLendingId||''))continue;
    const r=fp1052LendingRange(l);if(!r||!fp1052Overlap(a,b,r.start,r.end))continue;
    out.push({type:'Überlassung',id:String(l.id),title:l.fields.Title||'Fahrzeugüberlassung',status:l.fields.Status||'',start:r.start,end:r.end});
  }
  return out.sort((x,y)=>x.start-y.start);
}
function fp1052ConflictMessage(rows){
  return rows.map(x=>`${x.type}: ${x.title} · ${x.status||'offen'} · ${fp1052RangeText(x.start,x.end)}`).join('\n');
}
async function fp1052AssertVehicleAvailable(vehicleId,start,end,opts={}){
  const api=opts.api||await getCloud(),rows=await fp1052VehicleConflicts(api,vehicleId,start,end,opts);
  return {ok:rows.length===0,rows};
}
function fp1052RequestedUsageRange(){
  const now=new Date(),pf=document.getElementById('planFrom')?.value||'',pt=document.getElementById('planTo')?.value||'';
  if(pf&&pt){const a=fp1052LocalDayStart(pf),b=fp1052LocalDayEnd(pt);if(a&&b)return {start:a,end:b}}
  const end=new Date(now);end.setHours(23,59,59,999);return {start:now,end};
}
async function fp1052RefreshUsageAvailability(){
  const box=document.getElementById('fp1052UsageAvailability');if(!box||!S.vehicle?.id)return;
  box.className='muted';box.textContent='Fahrzeug-Verfügbarkeit wird geprüft …';
  try{const api=await getCloud(),r=fp1052RequestedUsageRange(),res=await fp1052AssertVehicleAvailable(S.vehicle.id,r.start,r.end,{api,excludeUsageId:S.usage?.cloudId||''});
    box.className=res.ok?'status-ok':'status-stop';box.innerHTML=res.ok?'✓ Fahrzeug im gewählten Zeitraum verfügbar':`<b>Fahrzeug bereits belegt</b><br>${res.rows.map(x=>esc(`${x.type} · ${x.status||''} · ${fp1052RangeText(x.start,x.end)}`)).join('<br>')}`;
  }catch(e){box.className='status-warn';box.textContent='Verfügbarkeit konnte nicht geprüft werden: '+e.message}
}
const fp1052SetupBase=setupBase;
setupBase=async function(){
  const r=await fp1052SetupBase();
  const card=app.querySelector('.card');if(card&&!document.getElementById('fp1052UsageAvailability')){
    const box=document.createElement('div');box.id='fp1052UsageAvailability';box.className='muted';box.style.marginTop='12px';card.appendChild(box);
    for(const id of ['planFrom','planTo'])document.getElementById(id)?.addEventListener('change',fp1052RefreshUsageAvailability);
    fp1052RefreshUsageAvailability();
  }
  return r;
};
const fp1052BeginCloud101Base=beginCloud101;
beginCloud101=async function(){
  try{const api=await getCloud(),r=fp1052RequestedUsageRange(),res=await fp1052AssertVehicleAvailable(S.vehicle.id,r.start,r.end,{api,excludeUsageId:S.usage?.cloudId||''});if(!res.ok)return alert('Dieses Fahrzeug ist im vorgesehenen Zeitraum bereits belegt:\n\n'+fp1052ConflictMessage(res.rows));}catch(e){return alert('Fahrzeug-Verfügbarkeit konnte nicht geprüft werden: '+e.message)}
  return fp1052BeginCloud101Base();
};
if(typeof beginCloud==='function')beginCloud=beginCloud101;

const fp1052StartPlannedUsageBase=startPlannedUsage;
startPlannedUsage=async function(id){
  try{const api=await getCloud(),u=await api.getItemByName('Nutzungen',id),now=new Date(),a=fp1052AsDate(u.fields.GeplanterBeginn)||now,b=fp1052AsDate(u.fields.GeplantesEndeDatum)||new Date(now.getTime()+24*3600*1000-1),start=a<now?a:now,res=await fp1052AssertVehicleAvailable(u.fields.FahrzeugId,start,b,{api,excludeUsageId:id});if(!res.ok)return alert('Start nicht möglich. Das Fahrzeug ist bereits belegt:\n\n'+fp1052ConflictMessage(res.rows));}catch(e){return alert('Fahrzeug-Verfügbarkeit konnte nicht geprüft werden: '+e.message)}
  return fp1052StartPlannedUsageBase(id);
};
const fp1052ContinueUsageBase=continueUsage;
continueUsage=async function(id){
  try{const api=await getCloud(),u=await api.getItemByName('Nutzungen',id),now=new Date(),end=new Date();end.setHours(23,59,59,999);const res=await fp1052AssertVehicleAvailable(u.fields.FahrzeugId,now,end,{api,excludeUsageId:id});if(!res.ok)return alert('Neue Tagesetappe nicht möglich. Das Fahrzeug ist bereits anderweitig belegt:\n\n'+fp1052ConflictMessage(res.rows));}catch(e){return alert('Fahrzeug-Verfügbarkeit konnte nicht geprüft werden: '+e.message)}
  return fp1052ContinueUsageBase(id);
};
if(typeof continueExistingUsage==='function'){
  const fp1052ContinueExistingBase=continueExistingUsage;
  continueExistingUsage=async function(id){
    try{const api=await getCloud(),u=await api.getItemByName('Nutzungen',id),now=new Date(),res=await fp1052AssertVehicleAvailable(u.fields.FahrzeugId,now,new Date(now.getTime()+60000),{api,excludeUsageId:id});if(!res.ok)return alert('Diese Nutzung kann nicht geöffnet werden, weil für das Fahrzeug gleichzeitig eine andere Belegung vorliegt:\n\n'+fp1052ConflictMessage(res.rows));}catch(e){return alert('Fahrzeug-Verfügbarkeit konnte nicht geprüft werden: '+e.message)}
    return fp1052ContinueExistingBase(id);
  };
}

