function fp1052LicenceFromText(v){const s=String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,' ');for(const k of ['C1E','C1','CE','BE','C','B'])if(new RegExp(`(^|\\s)${k}(\\s|$)`).test(s))return k;return''}
function fp1052LicenceSatisfies(have,need){const map={B:['B','BE','C1','C1E','C','CE'],BE:['BE','C1E','CE'],C1:['C1','C1E','C','CE'],C1E:['C1E','CE'],C:['C','CE'],CE:['CE']};return (map[need]||[need]).includes(have)}
function fp1052PersonHasLicence(personId,need,when){const at=fp1052AsDate(when)||new Date(),qs=(S.lendData?.quals||[]).filter(x=>String(x.fields.PersonId)===String(personId)&&x.fields.Aktiv!==false&&x.fields.Vorhanden!==false);return qs.some(q=>{const have=fp1052LicenceFromText(q.fields.Art||'');if(!have||!fp1052LicenceSatisfies(have,need))return false;const from=fp1052AsDate(q.fields.GueltigVon),to=fp1052AsDate(q.fields.GueltigBis);return (!from||from<=at)&&(!to||to>=at)})}
function fp1052FixedLicenceRule(vehicleId){return (S.lendData?.rules||[]).find(r=>String(r.fields.FahrzeugId)===String(vehicleId)&&r.fields.Aktiv!==false&&r.fields.Regelart==='Fahrerlaubnis'&&(r.fields.Bedingung==='Feste Fahrzeuganforderung'||(!r.fields.Bedingung&&r.fields.Pflichtgrad==='Pflicht')))}
function fp1052TrailerRule(r){return /anh[aä]nger|trailer/i.test(String(r?.fields?.Bedingung||''))}
function fp1052LendingAuthState(vehicleId){
  const v=(S.lendData?.vs||[]).find(x=>String(x.id)===String(vehicleId)),profile=normalizeProfile(v?.fields?.Profil||''),members=S.lendSelected||[],at=FP1052.lendingDraft?.from||new Date().toISOString(),errors=[],lines=[];
  if(profile==='motorhome'){
    const drivers=members.filter(m=>m.driveRole==='Fahrer'),fixed=fp1052FixedLicenceRule(vehicleId),need=fp1052LicenceFromText(fixed?.fields?.NachweisArt||'');
    if(!fixed||!need){lines.push('<div class="fp105-auth-line"><b>🔴 Grund-Fahrerlaubnis nicht festgelegt</b><span>Am Wohnmobil muss die erforderliche Fahrerlaubnisklasse hinterlegt sein.</span></div>');errors.push('Am Wohnmobil ist keine erforderliche Fahrerlaubnisklasse hinterlegt.')}else if(!drivers.length){lines.push(`<div class="fp105-auth-line"><b>🔴 Führerschein Klasse ${esc(need)}</b><span>Kein Fahrer in der Überlassung festgelegt.</span></div>`);errors.push('Mindestens eine Person muss als Fahrer festgelegt werden.')}else{const ok=drivers.some(d=>fp1052PersonHasLicence(d.personId,need,at));lines.push(`<div class="fp105-auth-line"><b>${ok?'🟢':'🔴'} Führerschein Klasse ${esc(need)}</b><span>${ok?'Mindestens ein eingetragener Fahrer besitzt eine passende gültige Fahrerlaubnis.':'Kein eingetragener Fahrer besitzt eine passende gültige Fahrerlaubnis.'}</span></div>`);if(!ok)errors.push(`Für die Grundanforderung Klasse ${need} ist kein geeigneter Fahrer hinterlegt.`)}
    const situ=(S.lendData?.rules||[]).filter(r=>String(r.fields.FahrzeugId)===String(vehicleId)&&r.fields.Aktiv!==false&&String(r.id)!==String(fixed?.id||'')&&(r.fields.Pflichtgrad==='Situativ'||fp1052TrailerRule(r)));for(const r of situ){if(fp1052TrailerRule(r)){if(!FP1052.lendingDraft?.trailer){lines.push(`<div class="fp105-auth-line"><b>🟡 ${esc(r.fields.NachweisArt||'Anhängerberechtigung')}</b><span>Kein Anhängerbetrieb geplant – diese Zusatzregel ist derzeit nicht aktiv.</span></div>`)}else{const n=fp1052LicenceFromText(r.fields.NachweisArt||''),ok=n&&drivers.some(d=>fp1052PersonHasLicence(d.personId,n,at));lines.push(`<div class="fp105-auth-line"><b>${ok?'🟢':'🔴'} ${esc(r.fields.NachweisArt||'Anhängerberechtigung')}</b><span>${ok?'Für den geplanten Anhängerbetrieb ist ein passender Fahrer vorhanden.':'Anhängerbetrieb geplant, aber keine passende Fahrerlaubnis gefunden.'}</span></div>`);if(!ok)errors.push('Für den geplanten Anhängerbetrieb fehlt eine passende Fahrerlaubnis.')}}else lines.push(`<div class="fp105-auth-line"><b>🟡 ${esc(r.fields.NachweisArt||'Situative Regel')}</b><span>${esc(r.fields.Bedingung||'situativ')} · im Reisecheck prüfen</span></div>`)}
    for(const m of members){const p=(S.lendData?.ps||[]).find(x=>String(x.id)===String(m.personId)),name=esc(p?.fields?.Anzeigename||p?.fields?.Title||'Person');if(m.driveRole!=='Fahrer')lines.push(`<div class="muted">${name} · ${esc(m.function||'Gast')} · kein Fahrer</div>`)}
  }else{
    const skippers=members.filter(m=>m.driveRole==='Skipper');if(!skippers.length){errors.push('Mindestens eine Person muss als Skipper festgelegt werden.');lines.push('<div class="fp105-auth-line"><b>🔴 Skipper fehlt</b><span>Für die Überlassung ist noch kein Skipper festgelegt.</span></div>')}else lines.push('<div class="fp105-auth-line"><b>🟢 Skipper festgelegt</b><span>Die revier- und nutzungsabhängigen Berechtigungen werden im Reisecheck weiter geprüft.</span></div>');
    const fixed=(S.lendData?.rules||[]).filter(r=>String(r.fields.FahrzeugId)===String(vehicleId)&&r.fields.Aktiv!==false&&r.fields.Pflichtgrad==='Pflicht'&&(!r.fields.Bedingung||r.fields.Bedingung==='Feste Fahrzeuganforderung'));for(const r of fixed){const ok=skippers.some(s=>typeof fp105QualMatches==='function'&&fp105QualMatches(r,s.personId));lines.push(`<div class="fp105-auth-line"><b>${ok?'🟢':'🔴'} ${esc(r.fields.NachweisArt||'Pflichtnachweis')}</b><span>${ok?'passender Nachweis hinterlegt':'bei keinem Skipper passender gültiger Nachweis gefunden'}</span></div>`);if(!ok)errors.push(`Pflichtnachweis fehlt: ${r.fields.NachweisArt||'Berechtigung'}`)}
  }
  return {errors,html:lines.join('')||'<p class="muted">Keine fachliche Regel hinterlegt.</p>'};
}
