function fp1052IsWaterskiName(v){return /wasserski/i.test(String(v||''))}
const fp1052CockpitBase=cockpit;
cockpit=async function(){await fp1052CockpitBase();if(fp1052IsWaterskiName(S.usage?.name))await fp1052AppendWaterskiCockpit()};
async function fp1052AppendWaterskiCockpit(){
  try{const api=await getCloud(),usageId=String(S.usage?.cloudId||''),[runs,legs,roles,people,nup]=await Promise.all([fp105SafeList(api,'WasserskiRuns'),fp105SafeList(api,'WasserskiRunEtappen'),fp105SafeList(api,'WasserskiRunPersonen'),fp105SafeList(api,'Personen'),fp105SafeList(api,'NutzungsPersonen')]),rs=runs.filter(x=>String(x.fields.NutzungId)===usageId).sort((a,b)=>String(a.fields.Beginn||'').localeCompare(String(b.fields.Beginn||''))),active=rs.find(x=>x.fields.Status==='Aktiv'),pm=Object.fromEntries(people.map(x=>[String(x.id),x.fields.Anzeigename||x.fields.Title])),crewIds=new Set(nup.filter(x=>String(x.fields.NutzungId)===usageId).map(x=>String(x.fields.PersonId))),pool=people.filter(x=>x.fields.Aktiv!==false&&(!crewIds.size||crewIds.has(String(x.id))));const roleName=(runId,fn)=>{const r=roles.find(x=>String(x.fields.RunId)===String(runId)&&x.fields.Funktion===fn&&x.fields.Aktiv!==false);return r?pm[String(r.fields.PersonId)]||'':''};
    const box=document.createElement('div');box.className='card';box.id='fp1052-waterski';box.innerHTML=`<div class="section first">Wasserski · Runs</div><p class="muted">Runs sind besondere Ereignisse dieser laufenden Nutzung und werden direkt hier bedient.</p>${active?`<div class="status-ok"><b>Run läuft seit ${typeof fp104Time==='function'?fp104Time(active.fields.Beginn):''}</b><div>Läufer: ${esc(pm[String(active.fields.SkilaeuferPersonId)]||'')} · Fahrer: ${esc(roleName(active.id,'Fahrer'))} · Beobachter: ${esc(roleName(active.id,'Beobachter'))}</div></div><div class="actions"><button onclick="fp1052AddWaterskiLeg('${active.id}')">Weitere Etappe</button><button class="primary" onclick="fp1052EndWaterskiRun('${active.id}')">Run beenden / Wechsel</button></div>`:`<div class="grid compact"><div class="field"><label>Skiläufer</label><select id="wsRunner"><option value="">– auswählen –</option>${pool.map(p=>`<option value="${p.id}">${esc(p.fields.Anzeigename||p.fields.Title)}</option>`).join('')}</select></div><div class="field"><label>Fahrer</label><select id="wsDriver"><option value="">– auswählen –</option>${pool.map(p=>`<option value="${p.id}">${esc(p.fields.Anzeigename||p.fields.Title)}</option>`).join('')}</select></div><div class="field"><label>Beobachter</label><select id="wsObserver"><option value="">– auswählen –</option>${pool.map(p=>`<option value="${p.id}">${esc(p.fields.Anzeigename||p.fields.Title)}</option>`).join('')}</select></div></div><button class="primary" onclick="fp1052StartWaterskiRun()">Run starten</button>`}<div class="section">Runs dieser Nutzung</div>${rs.slice(-8).reverse().map((r,i)=>{const n=rs.indexOf(r)+1,l=legs.filter(x=>String(x.fields.RunId)===String(r.id)).length;return `<div class="line"><div><b>Run ${n} · ${esc(pm[String(r.fields.SkilaeuferPersonId)]||'Läufer')}</b><div class="muted">${esc(r.fields.Status||'')} · ${l} Etappe(n)</div></div></div>`}).join('')||'<p class="muted">Noch kein Run.</p>'}<button onclick="fp1052MarkWaterskiReturn()">Rückfahrt zum Ausgangspunkt markieren</button>`;const sec=app.querySelector('.secondary');if(sec)sec.insertAdjacentElement('beforebegin',box);else app.appendChild(box);
  }catch(e){console.warn('Wasserski-Cockpit',e)}
}
async function fp1052WaterskiEvent(art,note=''){try{const api=await getCloud();await api.createItemByName('Ereignisse',{FahrzeugId:String(S.vehicle.id),NutzungId:String(S.usage.cloudId),TagesetappeId:String(S.day?.id||''),BenutzerId:'current',Art:art,Zeitpunkt:new Date().toISOString(),ErfasstAm:new Date().toISOString(),Herkunft:'Automatisch',Rohdaten:false,Notiz:note,Testdaten:testFlag(),Aktiv:true})}catch(e){console.warn(e)}}
async function fp1052StartWaterskiRun(){const runner=document.getElementById('wsRunner')?.value||'',driver=document.getElementById('wsDriver')?.value||'',observer=document.getElementById('wsObserver')?.value||'';if(!runner||!driver||!observer)return alert('Bitte Skiläufer, Fahrer und Beobachter auswählen.');if(new Set([runner,driver,observer]).size<3)return alert('Skiläufer, Fahrer und Beobachter müssen während eines Runs verschiedene Personen sein.');try{const api=await getCloud(),now=new Date().toISOString(),x=await api.createItemByName('WasserskiRuns',{NutzungId:String(S.usage.cloudId),SkilaeuferPersonId:runner,Beginn:now,Status:'Aktiv',Testdaten:testFlag(),Aktiv:true});for(const [id,fn] of [[runner,'Skiläufer'],[driver,'Fahrer'],[observer,'Beobachter']])await api.createItemByName('WasserskiRunPersonen',{RunId:String(x.id),PersonId:String(id),Funktion:fn,Aktiv:true,Testdaten:testFlag()});await api.createItemByName('WasserskiRunEtappen',{RunId:String(x.id),NutzungId:String(S.usage.cloudId),EtappeNr:1,Beginn:now,Status:'Aktiv',Testdaten:testFlag(),Aktiv:true});await fp1052WaterskiEvent('Wasserski · Run gestartet');await cockpit()}catch(e){alert(e.message)}}
async function fp1052AddWaterskiLeg(runId){try{const api=await getCloud(),all=(await fp105SafeList(api,'WasserskiRunEtappen')).filter(x=>String(x.fields.RunId)===String(runId)),active=all.find(x=>x.fields.Status==='Aktiv'),now=new Date().toISOString();if(active)await api.updateItemByName('WasserskiRunEtappen',active.id,{Status:'Beendet',Ende:now});await api.createItemByName('WasserskiRunEtappen',{RunId:String(runId),NutzungId:String(S.usage.cloudId),EtappeNr:all.length+1,Beginn:now,Status:'Aktiv',Testdaten:testFlag(),Aktiv:true});await fp1052WaterskiEvent('Wasserski · neue Etappe');await cockpit()}catch(e){alert(e.message)}}
async function fp1052EndWaterskiRun(runId){try{const api=await getCloud(),now=new Date().toISOString(),all=(await fp105SafeList(api,'WasserskiRunEtappen')).filter(x=>String(x.fields.RunId)===String(runId)&&x.fields.Status==='Aktiv');for(const l of all)await api.updateItemByName('WasserskiRunEtappen',l.id,{Status:'Beendet',Ende:now});await api.updateItemByName('WasserskiRuns',runId,{Status:'Beendet',Ende:now});await fp1052WaterskiEvent('Wasserski · Run beendet');await cockpit()}catch(e){alert(e.message)}}
async function fp1052MarkWaterskiReturn(){await fp1052WaterskiEvent('Wasserski · Rückfahrt zum Ausgangspunkt');alert('Rückfahrt zum Ausgangspunkt als Ereignis gespeichert.');await cockpit()}
startWaterskiRun=fp1052StartWaterskiRun;addWaterskiLeg=fp1052AddWaterskiLeg;endWaterskiRun=fp1052EndWaterskiRun;markWaterskiReturn=fp1052MarkWaterskiReturn;

const fp1052UsageDetailBase=usageDetail;
usageDetail=async function(){await fp1052UsageDetailBase();try{const api=await getCloud(),u=await api.getItemByName('Nutzungen',S.usageDetailId),[types,runs,people]=await Promise.all([fp105SafeList(api,'Nutzungsarten'),fp105SafeList(api,'WasserskiRuns'),fp105SafeList(api,'Personen')]),t=types.find(x=>String(x.id)===String(u.fields.NutzungsartId));if(!fp1052IsWaterskiName(t?.fields?.Name||t?.fields?.Title))return;[...app.querySelectorAll('button')].filter(b=>/Wasserski-Runs/i.test(b.textContent||'')).forEach(b=>b.remove());const pm=Object.fromEntries(people.map(x=>[String(x.id),x.fields.Anzeigename||x.fields.Title])),rs=runs.filter(x=>String(x.fields.NutzungId)===String(u.id)).sort((a,b)=>String(a.fields.Beginn||'').localeCompare(String(b.fields.Beginn||''))),box=document.createElement('div');box.className='card';box.innerHTML=`<div class="section first">Wasserski-Runs</div><p class="muted">Während einer aktiven Nutzung werden Runs direkt im Cockpit gestartet und beendet.</p>${rs.map((r,i)=>`<div class="line"><div><b>Run ${i+1} · ${esc(pm[String(r.fields.SkilaeuferPersonId)]||'Läufer')}</b><div class="muted">${fp1052DateLabel(r.fields.Beginn)} · ${esc(r.fields.Status||'')}</div></div></div>`).join('')||'<p class="muted">Noch keine Runs.</p>'}`;app.appendChild(box)}catch(e){console.warn(e)}};

